using System;
using System.Collections.Generic;
using Astrea.RunModifiers;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CompanionReward", menuName = "Data/Rewards/CompanionReward", order = 0)]
public class CompanionReward : Reward
{
	[Header("Companion Reward")]
	[SerializeField]
	private CompanionsTierListsList companionsTierListsList;

	[SerializeField]
	private ListRuntimeCompanionEvent OnRuntimeCompanionRewardsGenerated;

	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	private int companionRewardAmount;

	[SerializeField]
	private GameObject companionRewardPanelPrefab;

	[SerializeField]
	private GameObjectReference companionRewardPanelReference;

	[SerializeField]
	private CompanionRarity companionRarity;

	[SerializeField]
	private IntReference companionLevelRewardIntReference;

	[SerializeField]
	private CompanionRewardStartingEffect companionRewardStartingEffect;

	[SerializeField]
	private MapHandler mapHandler;

	[NonSerialized]
	public List<CompanionData> JustShuffledCompanionData = new List<CompanionData>();

	public override void GetReward()
	{
		if (companionRewardPanelReference.value == null)
		{
			JustShuffledCompanionData.Clear();
			companionRewardPanelReference.value = UnityEngine.Object.Instantiate(companionRewardPanelPrefab);
			companionRewardPanelReference.value.GetComponent<Canvas>().worldCamera = Camera.main;
		}
		int seedWithCurrentMapPlayerTrackerAndCurrentClearingRewardCount = mapHandler.GetSeedWithCurrentMapPlayerTrackerAndCurrentClearingRewardCount();
		if (JustShuffledCompanionData.Count == 0)
		{
			RandomUtilities.SetUnityEngineRandomInitStateSeed(seedWithCurrentMapPlayerTrackerAndCurrentClearingRewardCount);
		}
		List<RuntimeCompanion> runtimeCompanions = GetRuntimeCompanions(companionRewardAmount, higherLevelCompanion: false);
		OnRuntimeCompanionRewardsGenerated.Raise(runtimeCompanions);
		for (int i = 0; i < runtimeCompanions.Count; i++)
		{
			JustShuffledCompanionData.Add(runtimeCompanions[i].CompanionData);
		}
	}

	public List<RuntimeCompanion> GetRuntimeCompanions(int companionAmount, bool higherLevelCompanion)
	{
		List<CompanionData> companionDatas = GetCompanionDatas(companionAmount);
		List<RuntimeCompanion> list = new List<RuntimeCompanion>();
		int companionRewardLevelAndUpdateCompanionLevelRewardIntReference = GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference(higherLevelCompanion);
		for (int i = 0; i < companionDatas.Count; i++)
		{
			List<StartingEffect> list2 = new List<StartingEffect>();
			StartingEffect[] startingEffects = companionDatas[i].GetCompanionLevels()[companionRewardLevelAndUpdateCompanionLevelRewardIntReference].StartingEffects;
			for (int j = 0; j < startingEffects.Length; j++)
			{
				list2.Add(startingEffects[j]);
			}
			List<StartingEffect> list3 = new List<StartingEffect>();
			List<StartingEffect> sentinelStartingEffectsRunModifiers = ReferenceSingleton<RunModifiersManager>.Instance.SentinelStartingEffectsRunModifiers;
			for (int k = 0; k < sentinelStartingEffectsRunModifiers.Count; k++)
			{
				list3.Add(sentinelStartingEffectsRunModifiers[k]);
			}
			List<StartingEffect> sentinelStartingEffectOmenList = ReferenceSingleton<MiscOmensHandler>.Instance.SentinelStartingEffectOmenList;
			for (int l = 0; l < sentinelStartingEffectOmenList.Count; l++)
			{
				list3.Add(sentinelStartingEffectOmenList[l]);
			}
			StartingEffect[] startingEffects2 = companionRewardStartingEffect.CompanionRewardStartingEffects[companionRewardLevelAndUpdateCompanionLevelRewardIntReference].StartingEffects;
			if (startingEffects2.Length != 0)
			{
				list3.Add(startingEffects2.PickRandom());
			}
			list.Add(new RuntimeCompanion(companionDatas[i], companionRewardLevelAndUpdateCompanionLevelRewardIntReference, list2, list3));
		}
		return list;
	}

	private List<CompanionData> GetCompanionDatas(int amount)
	{
		CompanionRarityTier companionRarityTier = companionRarity.GetCompanionRarityTier();
		List<CompanionData> list = companionsTierListsList.GetCompanionsTierListCompanionDatas(companionRarityTier).Duplicate();
		CheckRemoveSentinelsFromList(list);
		list.RemoveAll((CompanionData companion) => JustShuffledCompanionData.Contains(companion));
		JustShuffledCompanionData.Clear();
		return list.PickRandom(amount);
	}

	public void CheckRemoveSentinelsFromList(List<CompanionData> possibleCompanions)
	{
		if (ReferenceSingleton<AssetsReference>.Instance.GameController.IsDailyRun)
		{
			possibleCompanions.RemoveAll((CompanionData companion) => companion.IsNewModdedCompanion());
		}
		possibleCompanions.RemoveAll((CompanionData companion) => currentCompanions.PlayerHasCompanion(companion));
		possibleCompanions.RemoveAll((CompanionData companion) => companion.Character != ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AnyCharacter && companion.Character != ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter);
		possibleCompanions.RemoveAll((CompanionData companion) => companion.CantBePickedAsReward);
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.GetCharacterLevel() <= 1)
		{
			possibleCompanions.RemoveAll((CompanionData companion) => companion.CompanionID.Replace(" ", "") == "UnknownDevice");
			possibleCompanions.RemoveAll((CompanionData companion) => companion.CompanionID.Replace(" ", "") == "HaywireThopter");
		}
	}

	public int GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference(bool higherLevelCompanion)
	{
		int num = Mathf.Max(GetSentinelShopRewardTimesVisitedBasedRewardLevel(), GetCompanionBasedRewardLevel(higherLevelCompanion));
		companionLevelRewardIntReference.SetValue(num);
		return num;
	}

	private int GetCompanionBasedRewardLevel(bool higherLevelCompanion)
	{
		int num = -1;
		if (currentCompanions.RuntimeCompanions.Count == 1)
		{
			return 0;
		}
		if (higherLevelCompanion)
		{
			int num2 = -1;
			for (int i = 0; i < currentCompanions.RuntimeCompanions.Count; i++)
			{
				int companionLevel = currentCompanions.RuntimeCompanions[i].CompanionLevel;
				if (companionLevel > num2)
				{
					num2 = companionLevel;
				}
			}
			num = num2 + 1;
			return Mathf.Clamp(num, 0, 4);
		}
		int num3 = 3;
		if (currentCompanions.RuntimeCompanions.Count <= 1)
		{
			num3 = -1;
		}
		else
		{
			for (int j = 0; j < currentCompanions.RuntimeCompanions.Count; j++)
			{
				int companionLevel2 = currentCompanions.RuntimeCompanions[j].CompanionLevel;
				if (companionLevel2 < num3)
				{
					num3 = companionLevel2;
				}
			}
		}
		num = num3 + 1;
		return Mathf.Clamp(num, 0, 4);
	}

	private int GetSentinelShopRewardTimesVisitedBasedRewardLevel()
	{
		return Mathf.Min(Mathf.FloorToInt((float)ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.SentinelShopOrRewardTimesVisitedCounter / 2f), 4);
	}
}
